//! Anti-aliased text from pre-rasterized 4-bit glyphs.
//!
//! Lay text out once with [`Line`] (glyph starts are computed then), place it
//! with [`Label`], and paint each label into the display rows it crosses; a
//! row outside a label's rows costs two comparisons. `Label::pixel` gives the
//! same result per pixel, for tests and readers. Faces are generated by
//! `packages/shell/fonts/generate.py`; see `docs/ui.md` for when to use each.
mod faces;

use super::row::Row;
use super::work;
use core::ops::Range;

pub use faces::{BODY, CAPTION, HERO, LARGE, TITLE, VALUE};

/// Anti-aliased glyphs may cover this many columns past a line's advance width.
pub const SPILL: usize = 2;

/// Every face, smallest first, for tools that read text back from frames.
pub static FACES: [&Face; 6] = [&CAPTION, &BODY, &TITLE, &VALUE, &LARGE, &HERO];

/// One glyph's box relative to its pen position and the face's top line.
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    pub offset: u16,
    pub x: i8,
    pub y: u8,
    pub w: u8,
    pub h: u8,
    pub advance: u8,
}

impl Glyph {
    pub const NONE: Self = Self {
        offset: 0,
        x: 0,
        y: 0,
        w: 0,
        h: 0,
        advance: 0,
    };
}

/// One weight at one size, covering ASCII from space to underscore.
pub struct Face {
    /// Line height from the top of the tallest glyph to the lowest descent.
    pub height: u8,
    /// Capital height, the visual size of the face.
    pub cap: u8,
    /// Rows above the cap line, for glyphs that rise over it.
    pub top: u8,
    pub glyphs: &'static [Glyph; 64],
    pub bits: &'static [u8],
}

impl Face {
    pub const fn glyph(&self, character: u8) -> &Glyph {
        let upper = character.to_ascii_uppercase();
        if upper < 0x20 || upper > 0x5f {
            return &self.glyphs[0];
        }
        &self.glyphs[(upper - 0x20) as usize]
    }

    /// The advance of `text`, in pixels.
    pub const fn width(&self, text: &[u8]) -> usize {
        let mut width = 0;
        let mut i = 0;
        while i < text.len() {
            width += self.glyph(text[i]).advance as usize;
            i += 1;
        }
        width
    }

    /// Where the ink of `text` ends, from its pen start: the advance less
    /// the last glyph's right bearing. Neighbours placed after it sit at the
    /// same distance from short glyphs such as "-" as from digits.
    pub const fn ink_width(&self, text: &[u8]) -> usize {
        let Some((&last, rest)) = text.split_last() else {
            return 0;
        };
        let glyph = self.glyph(last);
        let end = self.width(rest) as i32 + glyph.x as i32 + glyph.w as i32;
        if glyph.w == 0 || end < 0 {
            self.width(text)
        } else {
            end as usize
        }
    }

    /// Coverage 0..=15 of `character` at (x, y) from its pen position.
    pub fn coverage(&self, character: u8, x: i32, y: i32) -> u8 {
        let glyph = self.glyph(character);
        let gx = x - i32::from(glyph.x);
        let gy = y - i32::from(glyph.y);
        if gx < 0 || gy < 0 || gx >= i32::from(glyph.w) || gy >= i32::from(glyph.h) {
            return 0;
        }
        let stride = usize::from(glyph.w).div_ceil(2);
        let index = usize::from(glyph.offset) + gy as usize * stride + gx as usize / 2;
        let byte = self.bits[index];
        if gx % 2 == 0 { byte >> 4 } else { byte & 0x0f }
    }
}

/// Text laid out in one face: where each glyph starts.
#[derive(Clone, Copy)]
pub struct Line<const N: usize> {
    face: &'static Face,
    chars: [u8; N],
    starts: [u16; N],
    len: u8,
    width: u16,
}

impl<const N: usize> Line<N> {
    /// Text beyond `N` characters is cut.
    pub const fn new(face: &'static Face, text: &[u8]) -> Self {
        let mut line = Self {
            face,
            chars: [0; N],
            starts: [0; N],
            len: 0,
            width: 0,
        };
        let mut pen = 0;
        let mut i = 0;
        while i < text.len() && i < N {
            line.chars[i] = text[i].to_ascii_uppercase();
            line.starts[i] = pen;
            pen += face.glyph(text[i]).advance as u16;
            i += 1;
        }
        line.len = i as u8;
        line.width = pen;
        line
    }

    pub const fn face(&self) -> &'static Face {
        self.face
    }

    /// `text` in the first of `faces` (largest first) that fits `width`
    /// columns, anti-aliased edge included; else in the last face, cut to fit.
    pub fn fit(faces: &[&'static Face], text: &[u8], width: usize) -> Self {
        let Some((&smallest, larger)) = faces.split_last() else {
            return Self::new(&faces::BODY, b"");
        };
        for &face in larger {
            let line = Self::new(face, text);
            if line.width() + SPILL <= width {
                return line;
            }
        }
        let mut len = text.len().min(N);
        while len > 0 && smallest.width(&text[..len]) + SPILL > width {
            len -= 1;
        }
        Self::new(smallest, &text[..len])
    }

    pub const fn width(&self) -> usize {
        self.width as usize
    }

    pub const fn height(&self) -> usize {
        self.face.height as usize
    }

    pub fn text(&self) -> &[u8] {
        &self.chars[..usize::from(self.len)]
    }

    /// Coverage 0..=15 at (x, y) from the line's top-left corner.
    pub fn coverage(&self, x: usize, y: usize) -> u8 {
        if y >= usize::from(self.face.height) || x >= usize::from(self.width) + 2 {
            return 0;
        }
        let starts = &self.starts[..usize::from(self.len)];
        // The glyph whose cell holds x; a glyph may overhang into the next.
        let index = starts.partition_point(|&start| usize::from(start) <= x);
        let mut coverage = 0;
        let first = index.saturating_sub(2);
        for (start, &character) in starts[first..index].iter().zip(&self.chars[first..index]) {
            let dx = x as i32 - i32::from(*start);
            coverage = coverage.max(self.face.coverage(character, dx, y as i32));
        }
        coverage
    }
}

/// Put a glyph row's coverage from glyph column `skip` on into `out`, one
/// column per slot; the row packs two columns a byte, the left one in the
/// high nibble. `put` must leave a slot alone at coverage 0.
#[inline(always)]
fn unpack<T>(bits: &[u8], skip: usize, out: &mut [T], mut put: impl FnMut(&mut T, u8)) {
    if out.is_empty() {
        return;
    }
    let (odd, slots) = out.split_at_mut(skip % 2);
    let mut bytes = bits[skip / 2..].iter();
    if let [slot] = odd
        && let Some(&byte) = bytes.next()
    {
        put(slot, byte & 0x0f);
    }
    let (pairs, rest) = slots.as_chunks_mut::<2>();
    for ([left, right], &byte) in pairs.iter_mut().zip(&mut bytes) {
        // Glyph rows are mostly blank or solid.
        match byte {
            0 => {}
            0xff => {
                put(left, 15);
                put(right, 15);
            }
            _ => {
                put(left, byte >> 4);
                put(right, byte & 0x0f);
            }
        }
    }
    if let ([slot], Some(&byte)) = (rest, bytes.next()) {
        put(slot, byte >> 4);
    }
}

/// Coverage at glyph column `x` of a glyph row packed as `unpack` reads it.
fn nibble(bits: &[u8], x: usize) -> u8 {
    let byte = bits[x / 2];
    if x.is_multiple_of(2) {
        byte >> 4
    } else {
        byte & 0x0f
    }
}

/// Mix `color` over `background` by a 4-bit coverage. Full coverage is
/// exactly `color`, so the simulator can recognise solid glyph pixels.
pub fn blend(color: u16, background: u16, coverage: u8) -> u16 {
    match coverage {
        0 => background,
        15.. => color,
        a => {
            let a = u32::from(a);
            let mix = |shift: u32, mask: u32| {
                let fg = (u32::from(color) >> shift) & mask;
                let bg = (u32::from(background) >> shift) & mask;
                ((fg * a + bg * (15 - a) + 7) / 15) << shift
            };
            (mix(11, 0x1f) | mix(5, 0x3f) | mix(0, 0x1f)) as u16
        }
    }
}

/// One colour's blends over the background last seen, each coverage mixed
/// once: a label's anti-aliased edges mostly lie over one background.
struct Blends {
    color: u16,
    under: u16,
    /// Bit `a` is set once `mixed[a]` holds the blend at coverage `a`.
    known: u16,
    mixed: [u16; 16],
    mixes: u32,
}

impl Blends {
    const fn new(color: u16) -> Self {
        Self {
            color,
            under: 0,
            known: 0,
            mixed: [0; 16],
            mixes: 0,
        }
    }

    #[inline]
    fn over(&mut self, under: u16, coverage: u8) -> u16 {
        if under != self.under {
            self.under = under;
            self.known = 0;
        }
        let a = usize::from(coverage & 0x0f);
        if self.known & (1 << a) == 0 {
            self.mixed[a] = blend(self.color, under, coverage);
            self.known |= 1 << a;
            self.mixes += 1;
        }
        self.mixed[a]
    }

    #[inline(always)]
    fn put(&mut self, pixel: &mut u16, coverage: u8) {
        match coverage {
            0 => {}
            15.. => *pixel = self.color,
            a => *pixel = self.over(*pixel, a),
        }
    }
}

/// A glyph's last columns that lie in the next glyph's cell, and their
/// coverage, held until the next glyph adds its own.
#[derive(Default)]
struct Held {
    columns: Range<usize>,
    coverage: [u8; SPILL],
}

impl Held {
    /// Paint the held columns, each at the larger of its coverage and
    /// `next`'s, and hold none.
    #[inline(always)]
    fn paint(&mut self, pixels: &mut [u16], blends: &mut Blends, next: impl Fn(usize) -> u8) {
        for x in self.columns.clone() {
            let held = self.coverage.get(x - self.columns.start).copied();
            blends.put(&mut pixels[x], held.unwrap_or(0).max(next(x)));
        }
        self.columns = 0..0;
    }
}

/// How a label sits against its position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Align {
    Left,
    Center,
    Right,
}

/// A line of text placed on the canvas in one colour.
#[derive(Clone, Copy)]
pub struct Label<const N: usize> {
    pub line: Line<N>,
    pub left: usize,
    pub top: usize,
    pub color: u16,
}

impl<const N: usize> Label<N> {
    /// `x` is the left edge, centre or right edge as `align` says; `top` is
    /// the face's top line.
    pub const fn new(line: Line<N>, x: usize, top: usize, align: Align, color: u16) -> Self {
        let left = match align {
            Align::Left => x,
            Align::Center => x.saturating_sub(line.width() / 2),
            Align::Right => x.saturating_sub(line.width()),
        };
        Self {
            line,
            left,
            top,
            color,
        }
    }

    pub const fn right(&self) -> usize {
        self.left + self.line.width()
    }

    /// The columns the label can cover, anti-aliased edge included.
    pub const fn columns(&self) -> core::ops::Range<usize> {
        self.left..self.right() + SPILL
    }

    pub const fn bottom(&self) -> usize {
        self.top + self.line.height()
    }

    /// Blend the label over what the row already holds, glyph by glyph.
    /// Matches `pixel` over the same background, including where kerned
    /// glyphs overlap.
    #[inline]
    pub fn paint(&self, row: &mut Row) {
        let y = row.y();
        if y >= self.top && y < self.bottom() {
            self.paint_row(row, y);
        }
    }

    /// Most rows miss most labels, so the test above stays inline and the
    /// painting is one shared call.
    ///
    /// Each glyph paints its columns straight into the row. Only the last
    /// `SPILL` columns of a glyph can lie in the next glyph's cell, so the
    /// coverage there is held until the next glyph adds its own; a column
    /// takes the larger, as `Line::coverage` does.
    #[inline(never)]
    fn paint_row(&self, row: &mut Row, y: usize) {
        let clip = row.clip();
        let end = (self.right() + SPILL).min(clip.end);
        if self.left.max(clip.start) >= end {
            return;
        }
        // Columns from here on count from the label's left edge.
        let pixels = &mut row.pixels_mut()[self.left..end];
        let (from, to) = (clip.start.saturating_sub(self.left), pixels.len());
        let line = &self.line;
        let y = y - self.top;
        let starts = &line.starts[..usize::from(line.len)];
        // Like `Line::coverage`, a glyph reaches no further than the cell after next.
        let cell = |i: usize| {
            starts
                .get(i)
                .map_or(to, |&start| usize::from(start).min(to))
        };
        let mut blends = Blends::new(self.color);
        let mut columns = 0;
        let mut held = Held::default();
        for (i, (&start, &character)) in starts.iter().zip(&line.chars).enumerate() {
            let glyph = line.face.glyph(character);
            let gy = y.wrapping_sub(usize::from(glyph.y));
            if gy >= usize::from(glyph.h) {
                held.paint(pixels, &mut blends, |_| 0);
                continue;
            }
            let start = usize::from(start);
            let ink = start as isize + isize::from(glyph.x);
            let first = start.max(ink.max(0) as usize).max(from);
            let last = ((ink + isize::from(glyph.w)).max(0) as usize).min(cell(i + 2));
            let stride = usize::from(glyph.w).div_ceil(2);
            let base = usize::from(glyph.offset) + gy * stride;
            let bits = &line.face.bits[base..base + stride];
            let skip = |x: usize| (x as isize - ink) as usize;
            // A glyph's ink starts in its own cell, where the held columns start.
            let own = first.max(held.columns.end);
            held.paint(pixels, &mut blends, |x| {
                if (first..last).contains(&x) {
                    nibble(bits, skip(x))
                } else {
                    0
                }
            });
            let next = cell(i + 1);
            let own = own..last.min(next);
            if !own.is_empty() {
                columns += own.len();
                unpack(bits, skip(own.start), &mut pixels[own], |pixel, a| {
                    blends.put(pixel, a)
                });
            }
            if last > next {
                held.columns = first.max(next)..last;
                columns += held.columns.len();
                for (x, slot) in held.columns.clone().zip(&mut held.coverage) {
                    *slot = nibble(bits, skip(x));
                }
            }
        }
        held.paint(pixels, &mut blends, |_| 0);
        work::add(|work| {
            let inked = (from..to).filter(|&x| line.coverage(x, y) > 0);
            work.label_rows += 1;
            work.glyph_columns += columns as u64;
            work.glyph_pixels += inked.count() as u64;
            work.mixes += u64::from(blends.mixes);
        });
    }

    /// The label over `background`, or none where it has no ink.
    pub fn pixel(&self, x: usize, y: usize, background: u16) -> Option<u16> {
        if y < self.top || y >= self.bottom() || x < self.left {
            return None;
        }
        match self.line.coverage(x - self.left, y - self.top) {
            0 => None,
            coverage => Some(blend(self.color, background, coverage)),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn digits_share_one_advance_and_every_face_has_its_characters() {
        for face in [&CAPTION, &BODY, &TITLE, &VALUE, &LARGE, &HERO] {
            let advance = face.glyph(b'0').advance;
            assert!(
                b"0123456789"
                    .iter()
                    .all(|&d| face.glyph(d).advance == advance)
            );
            assert!(b"0123456789.:-%".iter().all(|&c| face.glyph(c).w > 0));
            assert!(face.glyph(b' ').advance > 0);
            assert!(face.cap <= face.height);
        }
        for face in [&CAPTION, &BODY, &TITLE] {
            assert!((b'A'..=b'Z').all(|c| face.glyph(c).w > 0));
            assert_eq!(face.glyph(b'a').advance, face.glyph(b'A').advance);
        }
    }

    /// `Label::paint_row` holds only `SPILL` columns of a glyph for the next.
    #[test]
    fn glyphs_spill_at_most_spill_columns_into_the_next_cell() {
        for face in FACES {
            for glyph in face.glyphs {
                let reach = i32::from(glyph.x) + i32::from(glyph.w);
                assert!(reach <= i32::from(glyph.advance) + SPILL as i32);
                assert!(glyph.w == 0 || glyph.x < glyph.advance as i8);
            }
        }
    }

    #[test]
    fn lines_lay_out_once_and_cover_their_glyphs() {
        const LINE: Line<8> = Line::new(&BODY, b"ride 12");
        assert_eq!(LINE.text(), b"RIDE 12");
        assert_eq!(LINE.width(), BODY.width(b"RIDE 12"));
        let mut solid = 0;
        let mut any = 0;
        for y in 0..LINE.height() {
            for x in 0..LINE.width() + 4 {
                let coverage = LINE.coverage(x, y);
                solid += usize::from(coverage == 15);
                any += usize::from(coverage > 0);
            }
        }
        assert!(solid > 40 && any > solid);
        assert_eq!(LINE.coverage(0, LINE.height()), 0);
        assert_eq!(Line::<2>::new(&BODY, b"LONG").text(), b"LO");
    }

    #[test]
    fn blending_keeps_full_coverage_exact_and_mixes_channels() {
        assert_eq!(blend(0xf800, 0, 15), 0xf800);
        assert_eq!(blend(0xf800, 0x07ff, 0), 0x07ff);
        let half = blend(0xffff, 0, 8);
        assert_eq!(half >> 11, (31 * 8 + 7) / 15);
        assert_eq!(blend(0x07e0, 0, 15), 0x07e0);
    }

    #[test]
    fn labels_align_and_clip_to_their_box() {
        let line = Line::<4>::new(&CAPTION, b"KM");
        let right = Label::new(line, 100, 10, Align::Right, 0xffff);
        assert_eq!(right.right(), 100);
        let centre = Label::new(line, 100, 10, Align::Center, 0xffff);
        assert_eq!(centre.left, 100 - line.width() / 2);
        assert_eq!(right.pixel(50, 10, 0), None);
        assert_eq!(right.pixel(right.left + 1, 9, 0), None);
        let lit = (10..right.bottom())
            .flat_map(|y| (right.left..right.right()).map(move |x| (x, y)))
            .filter(|&(x, y)| right.pixel(x, y, 0) == Some(0xffff))
            .count();
        assert!(lit > 10);
    }

    /// Glyph edges over a background that changes from pixel to pixel mix
    /// against each pixel's own background, as the per-pixel label does.
    #[test]
    fn painting_over_a_varied_background_matches_the_per_pixel_label() {
        let background = |x: usize, y: usize| {
            let mixed = (x as u32).wrapping_mul(2_654_435_761) ^ (y as u32).wrapping_mul(40_503);
            if x % 7 < 3 {
                0x2945
            } else {
                (mixed >> 16) as u16
            }
        };
        for face in FACES {
            let label = Label::new(
                Line::<16>::new(face, b"0:09 AVA 4.9%"),
                4,
                3,
                Align::Left,
                0xffe0,
            );
            for y in 0..label.bottom() + 1 {
                let mut pixels: [u16; 240] = core::array::from_fn(|x| background(x, y));
                label.paint(&mut Row::new(y, &mut pixels));
                for (x, &pixel) in pixels.iter().enumerate() {
                    let under = background(x, y);
                    assert_eq!(pixel, label.pixel(x, y, under).unwrap_or(under), "{x},{y}");
                }
            }
        }
    }

    /// Glyphs that reach into the next cell, before every glyph, alone and
    /// across a glyph with no advance.
    #[test]
    fn spilling_glyphs_paint_like_the_per_pixel_label() {
        const BACKGROUND: u16 = 0x2945;
        let characters = || 0x20u8..0x60;
        for face in FACES {
            let spills = characters().filter(|&c| {
                let glyph = face.glyph(c);
                i32::from(glyph.x) + i32::from(glyph.w) > i32::from(glyph.advance)
            });
            let empty = characters().find(|&c| face.glyph(c).advance == 0);
            for first in spills {
                for after in characters() {
                    for text in [&[first, after][..], &[first, empty.unwrap_or(b' '), after]] {
                        let label =
                            Label::new(Line::<4>::new(face, text), 3, 0, Align::Left, 0xffe0);
                        for y in 0..label.bottom() {
                            let mut pixels = [BACKGROUND; 160];
                            label.paint(&mut Row::new(y, &mut pixels));
                            for x in label.columns() {
                                let want = label.pixel(x, y, BACKGROUND).unwrap_or(BACKGROUND);
                                assert_eq!(pixels[x], want, "{text:?} at {x},{y}");
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn painting_a_row_matches_the_per_pixel_label() {
        const BACKGROUND: u16 = 0x2945;
        let texts: [&[u8]; 5] = [
            b"SETTINGS",
            b"0:09:59",
            b"AVA WTF 4.99 KM",
            b"T1/7%",
            b"9A9W7",
        ];
        for face in FACES {
            for text in texts {
                for (x, align) in [(3, Align::Left), (120, Align::Center), (236, Align::Right)] {
                    let label = Label::new(Line::<16>::new(face, text), x, 5, align, 0xffe0);
                    for y in 0..label.bottom() + 2 {
                        let mut pixels = [BACKGROUND; 240];
                        label.paint(&mut Row::new(y, &mut pixels));
                        for (x, &pixel) in pixels.iter().enumerate() {
                            let want = label.pixel(x, y, BACKGROUND).unwrap_or(BACKGROUND);
                            assert_eq!(pixel, want, "{:?} at {x},{y}", text);
                        }
                        // A clipped row keeps the pixels outside its clip.
                        let mut pixels = [BACKGROUND; 240];
                        label.paint(&mut Row::new(y, &mut pixels).within(100..140));
                        for (x, &pixel) in pixels.iter().enumerate() {
                            let want = if (100..140).contains(&x) {
                                label.pixel(x, y, BACKGROUND).unwrap_or(BACKGROUND)
                            } else {
                                BACKGROUND
                            };
                            assert_eq!(pixel, want, "clipped {:?} at {x},{y}", text);
                        }
                    }
                }
            }
        }
    }
}
